// Daily expiry check: SSL certificate, domain registration (RDAP), hosting (entered by hand).
const WARN = { ssl: 21, domain: 30, hosting: 30 };
const today = DateTime.now().setZone('Asia/Ho_Chi_Minh').startOf('day');
let tls = null;
try { tls = require('tls'); } catch (e) { tls = null; }
const TWO_LEVEL = ['co.uk', 'com.vn', 'net.vn', 'org.vn', 'edu.vn', 'gov.vn', 'com.au', 'net.au', 'co.nz', 'com.sg', 'co.jp', 'com.br'];
const rootDomain = host => { const p = host.split('.'); const last2 = p.slice(-2).join('.'); return TWO_LEVEL.includes(last2) ? p.slice(-3).join('.') : last2; };
const daysUntil = d => d ? Math.floor(DateTime.fromISO(d).startOf('day').diff(today, 'days').days) : null;
function sslInfo(host) {
  return new Promise(resolve => {
    if (!tls) return resolve({ error: 'SSL check disabled: add NODE_FUNCTION_ALLOW_BUILTIN=tls to n8n' });
    const sock = tls.connect({ host, port: 443, servername: host, rejectUnauthorized: false, timeout: 10000 }, () => {
      const c = sock.getPeerCertificate();
      const res = { valid_to: c && c.valid_to ? DateTime.fromJSDate(new Date(c.valid_to)).toISODate() : null, issuer: (c && c.issuer && (c.issuer.O || c.issuer.CN)) || '', authorized: sock.authorized, authError: sock.authorizationError ? String(sock.authorizationError) : null };
      sock.end(); resolve(res);
    });
    sock.on('error', e => resolve({ error: e.message }));
    sock.on('timeout', () => { sock.destroy(); resolve({ error: 'timeout' }); });
  });
}
const out = [];
for (const s of $input.all().map(i => i.json).filter(x => x.url && x.active !== false)) {
  const host = String(s.url).replace(/^https?:\/\//i, '').split(/[\/?#]/)[0].split(':')[0].toLowerCase();
  const ssl = await sslInfo(host);
  let domainExp = null, domainNote = '';
  try {
    const r = await this.helpers.httpRequest({ url: 'https://rdap.org/domain/' + rootDomain(host), json: true, timeout: 15000 });
    const ev = (r.events || []).find(e => e.eventAction === 'expiration');
    domainExp = ev ? ev.eventDate.slice(0, 10) : null;
    if (!ev) domainNote = 'registry does not publish expiry';
  } catch (e) { domainNote = 'no RDAP data for this domain'; }
  const sslDays = ssl.valid_to ? daysUntil(ssl.valid_to) : null;
  const domDays = daysUntil(domainExp);
  const hostDays = daysUntil(s.hosting_expires);
  const warnings = [];
  if (ssl.error) warnings.push('SSL check failed: ' + ssl.error);
  else if (sslDays !== null && sslDays < 0) warnings.push('SSL EXPIRED ' + (-sslDays) + ' day(s) ago');
  else if (ssl.authError && ssl.authError !== 'CERT_HAS_EXPIRED') warnings.push('SSL invalid: ' + ssl.authError);
  else if (sslDays !== null && sslDays <= WARN.ssl) warnings.push('SSL expires in ' + sslDays + ' day(s)');
  if (domDays !== null && domDays < 0) warnings.push('DOMAIN EXPIRED');
  else if (domDays !== null && domDays <= WARN.domain) warnings.push('Domain expires in ' + domDays + ' day(s)');
  if (hostDays !== null && hostDays < 0) warnings.push('HOSTING EXPIRED ' + (-hostDays) + ' day(s) ago (' + (s.hosting_provider || 'host') + ')');
  else if (hostDays !== null && hostDays <= WARN.hosting) warnings.push('Hosting (' + (s.hosting_provider || 'host') + ') renews in ' + hostDays + ' day(s)');
  out.push({ json: {
    id: s.id, name: s.name, url: s.url, client: s.client, status: s.status, response_ms: s.response_ms,
    ssl_expires: ssl.valid_to || '', ssl_days_left: sslDays, ssl_issuer: ssl.issuer || '',
    domain_expires: domainExp || '', domain_days_left: domDays, domain_note: domainNote,
    hosting_days_left: hostDays, warnings,
  } });
}
return out;

// Daily report: warnings first, then a one-line summary per site.
const rows = $('Check Expiry').all().map(i => i.json);
const d = n => n === null || n === undefined ? '-' : n + 'd';
const warn = rows.filter(r => r.warnings.length);
const lines = rows.map(r => (r.status === 'down' ? '[DOWN] ' : r.warnings.length ? '[!] ' : '[OK] ') + r.name + ' | SSL ' + d(r.ssl_days_left) + ' | domain ' + d(r.domain_days_left) + ' | hosting ' + d(r.hosting_days_left));
const text = 'DAILY WEBSITE REPORT - ' + DateTime.now().setZone('Asia/Ho_Chi_Minh').toFormat('dd LLL yyyy') + '
' + rows.length + ' sites, ' + rows.filter(r => r.status === 'up').length + ' up, ' + warn.length + ' need attention
'
  + (warn.length ? '
ACTION NEEDED
' + warn.map(r => '- ' + r.name + ': ' + r.warnings.join('; ')).join('
') + '
' : '')
  + '
ALL SITES (days left)
' + lines.join('
');
return [{ json: { text } }];
